#!/usr/bin/env python3
"""Clean-room reimplementation of the observed cmatrix executable.

This program intentionally implements only behavior observed through the
provided binary's public interface and bundled docs.  It does not depend on or
invoke the original executable.
"""
import errno
import fcntl
import os
import random
import select
import signal
import shutil
import string
import sys
import termios
import time
import tty as ttymod
from dataclasses import dataclass

USAGE = ''' Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]
 -a: Asynchronous scroll
 -b: Bold characters on
 -B: All bold characters (overrides -b)
 -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts
 -f: Force the linux $TERM type to be on
 -l: Linux mode (uses matrix console font)
 -L: Lock mode (can be closed from another terminal)
 -o: Use old-style scrolling
 -h: Print usage and exit
 -n: No bold characters (overrides -b and -B, default)
 -s: "Screensaver" mode, exits on first keystroke
 -x: X window mode, use if your xterm is using mtx.pcf
 -V: Print version information and exit
 -M [message]: Prints your message in the center of the screen. Overrides -L's default message.
 -u delay (0 - 10, default 4): Screen update delay
 -C [color]: Use this color for matrix (default green)
 -r: rainbow mode
 -m: lambda mode
 -k: Characters change while scrolling. (Works without -o opt.)
 -t [tty]: Set tty to use
'''

VERSION = ''' CMatrix version 2.0 (compiled 19:59:42, Apr 17 2026)
Email: abishekvashok@gmail.com
Web: https://github.com/abishekvashok/cmatrix
'''

INVALID_COLOR = ''' Invalid color selection
 Valid colors are green, red, blue, white, yellow, cyan, magenta and black.
'''

COLOR_CODES = {
    'black': 30,
    'red': 31,
    'green': 32,
    'yellow': 33,
    'blue': 34,
    'magenta': 35,
    'cyan': 36,
    'white': 37,
}
COLOR_KEYS = {
    '!': 'red',
    '@': 'green',
    '#': 'yellow',
    '$': 'blue',
    '%': 'magenta',
    '^': 'cyan',
    '&': 'white',
    ')': 'black',
}
RAINBOW = [31, 32, 33, 34, 35, 36, 37]

# The original mostly uses printable ASCII unless special font modes are set.
ASCII_CHARS = ''.join(chr(i) for i in range(33, 127))
# A conservative ASCII approximation for the Japanese/font modes; the real
# program relies on console/xterm fonts, so these bytes are what matters more
# than Unicode semantics in most terminals.
JAPANESE_APPROX = '@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~'
LAMBDA_APPROX = 'lambdaMATRIX01'


@dataclass
class Options:
    async_scroll: bool = False
    bold_mode: int = 0        # 0 none, 1 random, 2 all
    force_linux: bool = False
    linux_mode: bool = False
    old_style: bool = False
    screensaver: bool = False
    lock: bool = False
    x_mode: bool = False
    rainbow: bool = False
    lambda_mode: bool = False
    change_all: bool = False
    japanese: bool = False
    update: int = 4
    color_name: str = 'green'
    message: str | None = None
    tty_path: str | None = None


def c_atoi(s: str) -> int:
    """Small C atoi clone for option -u."""
    i = 0
    n = len(s)
    while i < n and s[i] in ' \t\n\r\v\f':
        i += 1
    sign = 1
    if i < n and s[i] in '+-':
        if s[i] == '-':
            sign = -1
        i += 1
    val = 0
    seen = False
    while i < n and s[i].isdigit():
        seen = True
        val = val * 10 + (ord(s[i]) - 48)
        i += 1
    return sign * val if seen else 0


def parse_args(argv: list[str]) -> tuple[str, Options | None]:
    """Parse options with GNU-getopt-like behavior observed from the binary.

    Returns (action, options).  action is one of: run, usage, version,
    invalid_color.
    """
    opts = Options()
    i = 0
    argc = len(argv)
    options_with_args = {'u', 'C', 'M', 't'}
    valid_noarg = set('abBcfhlLonsmxVrk?')

    while i < argc:
        arg = argv[i]
        if arg == '--':
            break
        # GNU getopt permutes non-options by default.  For this reimplementation
        # it is sufficient to skip over them and continue looking for options.
        if not arg.startswith('-') or arg == '-':
            i += 1
            continue
        if arg.startswith('--'):
            return 'usage', None

        j = 1
        while j < len(arg):
            ch = arg[j]
            if ch in options_with_args:
                if j + 1 < len(arg):
                    optarg = arg[j + 1:]
                    j = len(arg)
                else:
                    i += 1
                    if i >= argc:
                        return 'usage', None
                    optarg = argv[i]
                    j = len(arg)
                if ch == 'u':
                    opts.update = c_atoi(optarg)
                elif ch == 'C':
                    name = optarg.lower()
                    if name not in COLOR_CODES:
                        return 'invalid_color', None
                    opts.color_name = name
                    opts.rainbow = False
                elif ch == 'M':
                    opts.message = optarg
                elif ch == 't':
                    opts.tty_path = optarg
                break
            elif ch in valid_noarg:
                if ch in ('h', '?'):
                    return 'usage', None
                if ch == 'V':
                    return 'version', None
                if ch == 'a':
                    opts.async_scroll = True
                elif ch == 'b':
                    opts.bold_mode = 1
                elif ch == 'B':
                    opts.bold_mode = 2
                elif ch == 'n':
                    opts.bold_mode = 0
                elif ch == 'c':
                    opts.japanese = True
                elif ch == 'f':
                    opts.force_linux = True
                elif ch == 'l':
                    opts.linux_mode = True
                elif ch == 'L':
                    opts.lock = True
                    if opts.message is None:
                        opts.message = 'Computer locked.'
                elif ch == 'o':
                    opts.old_style = True
                elif ch == 's':
                    opts.screensaver = True
                elif ch == 'm':
                    opts.lambda_mode = True
                elif ch == 'x':
                    opts.x_mode = True
                elif ch == 'r':
                    opts.rainbow = True
                elif ch == 'k':
                    opts.change_all = True
                j += 1
            else:
                return 'usage', None
        i += 1
    return 'run', opts


def open_tty_if_requested(path: str | None) -> bool:
    if not path:
        return True
    try:
        fd = os.open(path, os.O_RDWR)
    except OSError as e:
        sys.stderr.write(f"cmatrix: error: '{path}' couldn't be opened: {e.strerror}.\n")
        sys.stderr.flush()
        return False
    # The observed program redirects the terminal streams before initializing
    # curses, so later errors may go to the selected tty as well.
    for target in (0, 1, 2):
        try:
            os.dup2(fd, target)
        except OSError:
            pass
    if fd > 2:
        os.close(fd)
    # Re-wrap standard streams after dup2 so Python writes to the new fds.
    try:
        sys.stdin = os.fdopen(0, 'r', buffering=1, encoding='utf-8', errors='ignore', closefd=False)
        sys.stdout = os.fdopen(1, 'w', buffering=1, encoding='utf-8', errors='ignore', closefd=False)
        sys.stderr = os.fdopen(2, 'w', buffering=1, encoding='utf-8', errors='ignore', closefd=False)
    except Exception:
        pass
    return True


def terminfo_exists(term: str) -> bool:
    if not term:
        return False
    # Common terminfo locations.  ncurses stores entries under the first
    # character; some systems also use a hexadecimal directory name.
    first = term[0]
    hexf = f"{ord(first):x}"
    roots = [
        os.environ.get('TERMINFO', ''),
        '/etc/terminfo', '/lib/terminfo', '/usr/share/terminfo',
        '/usr/lib/terminfo', '/usr/local/share/terminfo',
    ]
    for root in roots:
        if not root:
            continue
        if os.path.exists(os.path.join(root, first, term)):
            return True
        if os.path.exists(os.path.join(root, hexf, term)):
            return True
    # A small fallback for ubiquitous names in very small containers.
    return term in {'xterm', 'xterm-256color', 'screen', 'screen-256color', 'linux', 'vt100', 'dumb', 'ansi'}


def validate_terminal() -> tuple[bool, str]:
    term = os.environ.get('TERM') or 'unknown'
    if not terminfo_exists(term):
        sys.stderr.write(f"Error opening terminal: {term}.\n")
        sys.stderr.flush()
        return False, term
    return True, term


class MatrixDisplay:
    def __init__(self, opts: Options, term: str):
        self.opts = opts
        self.term = 'linux' if opts.force_linux else term
        size = shutil.get_terminal_size((80, 24))
        self.cols = max(1, size.columns)
        self.rows = max(1, size.lines)
        self.color_code = COLOR_CODES.get(opts.color_name, 32)
        self.cleaned = False
        self.started = False
        self.stdin_closed = False
        self.saved_termios = None
        self.streams: list[dict[str, int]] = []
        self.random = random.Random()
        self.random.seed(int(time.time() * 1000000) ^ os.getpid())
        self._setup_streams()

    def _setup_streams(self) -> None:
        self.streams = []
        for x in range(1, self.cols + 1, 2):
            length = self.random.randint(3, max(4, min(self.rows + 3, 30)))
            head = self.random.randint(-self.rows, self.rows)
            speed = self.random.randint(1, 3)
            self.streams.append({'x': x, 'head': head, 'len': length, 'tick': 0, 'speed': speed})

    def write(self, s: str) -> None:
        try:
            sys.stdout.write(s)
        except (BrokenPipeError, OSError):
            raise SystemExit(0)

    def flush(self) -> None:
        try:
            sys.stdout.flush()
        except (BrokenPipeError, OSError):
            raise SystemExit(0)

    def using_linux_sequences(self) -> bool:
        return self.term == 'linux'

    def using_dumb(self) -> bool:
        return self.term == 'dumb'

    def startup_normal(self) -> None:
        self.started = True
        if self.using_dumb():
            return
        if self.using_linux_sequences():
            self.write(f"\x1b)0\x1b[1;{self.rows}r\x1b[m\x0f\x1b[4l\x1b[?7h\x1b[?25l\x1b[?1c"
                       f"\x1b[39;49m\x1b[39;49m\x1b[m\x0f\x1b[H\x1b[J")
        elif self.term.startswith('vt'):
            self.write(f"\x1b(B\x1b)0\x1b[1;{self.rows}r\x1b[m\x0f\x1b[?7h\x1b[H\x1b[J")
        else:
            self.write(f"\x1b[?1049h\x1b[22;0;0t\x1b[1;{self.rows}r\x1b(B\x1b[m\x1b[4l\x1b[?7h\x1b[?25l"
                       f"\x1b[39;49m\x1b[39;49m\x1b(B\x1b[m\x1b[H\x1b[2J")
        self.flush()

    def startup_for_linux_font_failure(self) -> None:
        self.started = True
        if self.using_dumb():
            return
        if self.using_linux_sequences():
            self.write(f"\x1b)0\x1b[1;{self.rows}r\x1b[m\x0f\x1b[4l\x1b[?7h\x1b[?25l\x1b[?1c")
        elif self.term.startswith('vt'):
            self.write(f"\x1b(B\x1b)0\x1b[1;{self.rows}r\x1b[m\x0f\x1b[?7h")
        else:
            self.write(f"\x1b[?1049h\x1b[22;0;0t\x1b[1;{self.rows}r\x1b(B\x1b[m\x1b[4l\x1b[?7h\x1b[?25l")
        self.flush()

    def cleanup(self, clear: bool = True) -> None:
        if self.cleaned:
            return
        self.cleaned = True
        # Restore input mode first so a terminal remains usable even if stdout
        # is redirected and writing cleanup sequences fails.
        if self.saved_termios is not None:
            try:
                termios.tcsetattr(0, termios.TCSADRAIN, self.saved_termios)
            except Exception:
                pass
        if not self.started or self.using_dumb():
            self.flush()
            return
        try:
            if self.using_linux_sequences():
                if clear:
                    self.write(f"\x1b[?25h\x1b[?0c\x1b[H\x1b[J\x1b[{self.rows};1H\r")
                else:
                    self.write(f"\x1b[?25h\x1b[?0c\x1b[{self.rows};1H\r")
            elif self.term.startswith('vt'):
                if clear:
                    self.write(f"\x1b[H\x1b[J\x1b[{self.rows};1H\r\x1b[?1l\x1b>")
                else:
                    self.write(f"\x1b[{self.rows};1H\r\x1b[?1l\x1b>")
            else:
                if clear:
                    self.write(f"\x1b[?12l\x1b[?25h\x1b[H\x1b[2J\x1b[{self.rows};1H\x1b[?1049l\x1b[23;0;0t\r\x1b[?1l\x1b>")
                else:
                    self.write(f"\x1b[{self.rows};1H\x1b[?12l\x1b[?25h\x1b[?1049l\x1b[23;0;0t\r\x1b[?1l\x1b>")
            self.flush()
        except Exception:
            pass

    def setup_input(self) -> None:
        try:
            if os.isatty(0):
                self.saved_termios = termios.tcgetattr(0)
                ttymod.setcbreak(0)
        except Exception:
            self.saved_termios = None

    def read_key(self) -> str | None:
        if self.stdin_closed:
            return None
        try:
            r, _, _ = select.select([0], [], [], 0)
        except Exception:
            self.stdin_closed = True
            return None
        if not r:
            return None
        try:
            data = os.read(0, 1)
        except BlockingIOError:
            return None
        except OSError:
            self.stdin_closed = True
            return None
        if not data:
            self.stdin_closed = True
            return None
        try:
            return data.decode('utf-8', 'ignore') or chr(data[0])
        except Exception:
            return chr(data[0])

    def handle_key(self, ch: str) -> bool:
        """Return True if the program should exit."""
        if ch is None:
            return False
        if self.opts.screensaver:
            return True
        if ch == 'q':
            return not self.opts.lock
        if ch == 'a':
            self.opts.async_scroll = not self.opts.async_scroll
        elif ch == 'b':
            self.opts.bold_mode = 1
        elif ch == 'B':
            self.opts.bold_mode = 2
        elif ch == 'n':
            self.opts.bold_mode = 0
        elif ch in '0123456789':
            self.opts.update = ord(ch) - 48
        elif ch in COLOR_KEYS:
            self.opts.color_name = COLOR_KEYS[ch]
            self.color_code = COLOR_CODES[self.opts.color_name]
            self.opts.rainbow = False
        return False

    def color_for_cell(self, head: bool = False) -> int:
        if self.opts.rainbow:
            return self.random.choice(RAINBOW)
        if head and not self.opts.japanese:
            # The observed default highlights the newest character in white.
            return 37
        return self.color_code

    def style_prefix(self, code: int, force_bold: bool = False) -> str:
        bold = force_bold or self.opts.bold_mode == 2 or (self.opts.bold_mode == 1 and self.random.randrange(8) == 0)
        if bold:
            if self.using_linux_sequences():
                return f"\x1b[0;1m\x1b[{code}m"
            return f"\x1b(B\x1b[0;1m\x1b[{code}m"
        return f"\x1b[{code}m"

    def reset_suffix(self) -> str:
        if self.using_linux_sequences():
            return "\x1b[39m\x1b[m\x0f"
        return "\x1b[39m\x1b(B\x1b[m"

    def cell(self, ch: str, code: int | None = None, head: bool = False) -> str:
        if code is None:
            code = self.color_for_cell(head=head)
        return self.style_prefix(code) + ch + self.reset_suffix()

    def cursor(self, y: int, x: int) -> str:
        y = max(1, min(self.rows, y))
        x = max(1, min(self.cols, x))
        return f"\x1b[{y};{x}H"

    def random_char(self) -> str:
        if self.opts.lambda_mode:
            # In ordinary xterm mode the original still emits one-byte glyphs;
            # using a lambda-flavoured ASCII set keeps terminal width stable.
            return self.random.choice(LAMBDA_APPROX)
        if self.opts.japanese or self.opts.x_mode or self.opts.force_linux:
            return self.random.choice(JAPANESE_APPROX)
        return self.random.choice(ASCII_CHARS)

    def initial_fill(self) -> None:
        if self.using_dumb():
            # Dumb terminal: the original cannot do colors/cursor motion and
            # mostly streams spaces and carriage returns.
            for _ in range(self.rows):
                self.write(' ' * max(0, self.cols - 1) + '\r')
            self.flush()
            return
        pieces: list[str] = []
        for y in range(1, self.rows + 1):
            for x in range(1, self.cols + 1, 2):
                code = self.random.choice(RAINBOW) if self.opts.rainbow else self.color_code
                pieces.append(self.cell(' ', code=code, head=False))
                if x + 1 <= self.cols:
                    pieces.append(' ')
            if y < self.rows:
                pieces.append(f"\r\x1b[{y + 1}d")
        self.write(''.join(pieces))
        self.draw_message()
        self.flush()

    def draw_at(self, y: int, x: int, ch: str, head: bool = False, erase: bool = False) -> None:
        if y < 1 or y > self.rows or x < 1 or x > self.cols:
            return
        if self.using_dumb():
            return
        if erase:
            ch = ' '
            head = False
        self.write(self.cursor(y, x) + self.cell(ch, head=head))

    def draw_message(self) -> None:
        msg = self.opts.message
        if not msg or self.using_dumb():
            return
        # The original prints the message in the middle over the rain, with a
        # little blank space around it because the underlying columns are on
        # alternating cells.  Keep it unadorned so it remains readable.
        visible = f"  {msg}  "
        y = max(1, min(self.rows, self.rows // 2 + 1))
        x = max(1, (self.cols - len(visible)) // 2 + 1)
        self.write(self.cursor(y, x) + "\x1b[39m\x1b(B\x1b[m" + visible)

    def frame(self) -> None:
        for st in self.streams:
            if self.opts.async_scroll:
                st['tick'] += 1
                if st['tick'] % st['speed'] != 0:
                    # Character-change mode still sparkles inside slow streams.
                    if self.opts.change_all and 1 <= st['head'] <= self.rows and self.random.randrange(3) == 0:
                        self.draw_at(st['head'], st['x'], self.random_char(), head=True)
                    continue
            old_head = st['head']
            new_head = old_head + 1
            st['head'] = new_head

            # The previous head becomes part of the trail.
            if 1 <= old_head <= self.rows:
                self.draw_at(old_head, st['x'], self.random_char() if self.opts.change_all else self.random_char(), head=False)

            # Optional sparkle: redraw a few cells in the existing trail.
            if self.opts.change_all:
                low = max(1, new_head - st['len'] + 1)
                high = min(self.rows, new_head - 1)
                if low <= high:
                    for _ in range(1 if self.rows < 20 else 2):
                        self.draw_at(self.random.randint(low, high), st['x'], self.random_char(), head=False)

            # Draw the new head.
            if 1 <= new_head <= self.rows:
                self.draw_at(new_head, st['x'], self.random_char(), head=True)

            # Erase the tail.
            tail = new_head - st['len']
            if 1 <= tail <= self.rows:
                self.draw_at(tail, st['x'], ' ', erase=True)

            if new_head - st['len'] > self.rows:
                st['head'] = -self.random.randint(0, self.rows)
                st['len'] = self.random.randint(3, max(4, min(self.rows + 3, 40)))
                st['speed'] = self.random.randint(1, 3)
                st['tick'] = 0
        self.draw_message()
        self.flush()

    def sleep_delay(self) -> None:
        # The C program's delay is roughly centiseconds.  Negative and nonnumeric
        # values turn into a very small/no delay via atoi/usleep behavior.
        u = self.opts.update
        if u <= 0:
            time.sleep(0.001)
        else:
            time.sleep(min(0.25, u * 0.01))

    def run(self) -> int:
        self.setup_input()
        self.startup_normal()
        # Process one pending keystroke before the first full-screen draw.  This
        # matches the observed piped-input behavior for 'q' and -s.
        first = self.read_key()
        if first is not None and self.handle_key(first):
            self.cleanup(clear=True)
            return 0
        self.initial_fill()
        while True:
            ch = self.read_key()
            if ch is not None and self.handle_key(ch):
                self.cleanup(clear=True)
                return 0
            self.frame()
            self.sleep_delay()


_current_display: MatrixDisplay | None = None


def _signal_handler(signum, frame):  # noqa: ANN001 - signal API
    global _current_display
    if _current_display is not None:
        _current_display.cleanup(clear=False)
    raise SystemExit(0)


def run_linux_mode_failure(opts: Options, term: str) -> int:
    display = MatrixDisplay(opts, term)
    display.startup_for_linux_font_failure()
    display.cleanup(clear=True)
    sys.stderr.write(' Unable to use both "setfont" and "consolechars".\n')
    sys.stderr.flush()
    return 0


def main(argv: list[str]) -> int:
    global _current_display
    action, opts = parse_args(argv)
    if action == 'usage':
        sys.stdout.write(USAGE)
        return 0
    if action == 'version':
        sys.stdout.write(VERSION)
        return 0
    if action == 'invalid_color':
        sys.stderr.write(INVALID_COLOR)
        return 0
    assert opts is not None

    if not open_tty_if_requested(opts.tty_path):
        return 1

    ok, term = validate_terminal()
    if not ok:
        return 1

    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)
    try:
        if opts.linux_mode:
            return run_linux_mode_failure(opts, 'linux' if opts.force_linux else term)
        display = MatrixDisplay(opts, term)
        _current_display = display
        return display.run()
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else 0
        return code
    except KeyboardInterrupt:
        if _current_display is not None:
            _current_display.cleanup(clear=False)
        return 0
    finally:
        if _current_display is not None and not _current_display.cleaned:
            _current_display.cleanup(clear=False)


if __name__ == '__main__':
    raise SystemExit(main(sys.argv[1:]))
